session_start();header('Content-Type: application/json; charset=UTF-8');require_once __DIR__.'/../config/koneksi.php';if(empty($_SESSION['user_id'])){echo json_encode(['success'=>true,'user'=>null]);exit;}$q=$conn->prepare("SELECT u.id,u.nama,u.email,u.angkatan,u.tahun_lulus,u.foto,u.jurusan_id,u.universitas_id,j.nama AS fakultas,v.nama AS universitas FROM users u LEFT JOIN jurusan j ON j.id=u.jurusan_id LEFT JOIN universitas v ON v.id=u.universitas_id WHERE u.id=? AND u.role='user'");$q->bind_param('i',$_SESSION['user_id']);$q->execute();$user=$q->get_result()->fetch_assoc();if(!$user){$_SESSION=[];session_destroy();echo json_encode(['success'=>true,'user'=>null]);exit;}echo json_encode(['success'=>true,'user'=>$user],JSON_UNESCAPED_UNICODE);